import { Mesh, Mesh, MeshGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;

  // Root object
  const root = new Group();
  root.userData.handlers = {};
  const cleanupFns = [];

  // Plane geometry based on atlas region (512x320 => 1.6:1 aspect)
  const planeWidth = 1.6;
  const planeHeight = 1;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial();
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture and apply via node
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = texture(tex);
      material.needsUpdate = true;
    });
  }

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        cleanupFns.push(() => {
          if (instance && typeof instance.cleanup === 'function') instance.cleanup();
        });
      }
    }
  }

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines stored
    cleanupFns.forEach((fn) => fn());

    // Clear handlers
    root.userData.handlers = {};
  };

  return root;
}
